import { serveRelay } from '@/relay.js';
import { resolveBrowserToken } from '../src/token-auth.js';

const PORT = parseInt(process.env.PORT || '9224', 10);
const HOST = process.env.HOST || '127.0.0.1';

// Phase 3 M1 §5.3 — the relay requires a bearer token on every HTTP request
// and WebSocket connection. The token is generated by the spawning side and
// must arrive in ACCOMPLISH_DEV_BROWSER_TOKEN; without it consumers cannot
// authenticate, so fail fast instead of silently starting an unusable relay
// unless the launcher explicitly sets the token via env.
const TOKEN = process.env.ACCOMPLISH_DEV_BROWSER_TOKEN;
if (!TOKEN || TOKEN.trim().length === 0) {
  console.error(
    'ACCOMPLISH_DEV_BROWSER_TOKEN is not set — refusing to start an unauthenticated relay.\n' +
      'Spawn via ensureDevBrowserServer, or set ACCOMPLISH_DEV_BROWSER_TOKEN explicitly.',
  );
  process.exit(1);
}

async function main() {
  // Token resolution is re-validated inside serveRelay (same env var).
  resolveBrowserToken();
  const server = await serveRelay({
    port: PORT,
    host: HOST,
  });

  const shutdown = async () => {
    console.log('\nShutting down relay server...');
    await server.stop();
    process.exit(0);
  };

  process.on('SIGINT', shutdown);
  process.on('SIGTERM', shutdown);
}

main().catch((err) => {
  console.error('Failed to start relay server:', err);
  process.exit(1);
});
